def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_me = me[-1]
    last_opp = opp[-1]

    opp_def_total = sum(1 for a in opp if a == 'D')
    me_def_total = sum(1 for a in me if a == 'D')
    opp_c = n - opp_def_total

    # Hard detection: always defect
    if opp_def_total == n and n >= 3:
        return 'D'

    # Hard detection: always cooperate -> exploit moderately but not suicide
    if opp_c == n and n >= 5:
        # Probe occasionally, but if they keep cooperating, defect more late
        if n >= 90:
            return 'D'
        if n >= 30 and rng.random() < 0.5:
            return 'D'
        if rng.random() < 0.15:
            return 'D'
        return 'C'

    # Recent window stats
    w10 = min(n, 10)
    opp_def10 = sum(1 for a in opp[-w10:] if a == 'D')
    me_def10 = sum(1 for a in me[-w10:] if a == 'D')

    # Persistent defector: match defection
    if w10 >= 5 and opp_def10 >= w10 - 1:
        return 'D'

    # Endgame: last 8 rounds exploit cooperative opponent
    if n >= 92:
        if opp_def_total * 2 < n:
            return 'D'
        return 'D' if last_opp == 'C' else 'D'

    # If opponent just defected and we cooperated: retaliate strongly
    if last_opp == 'D' and last_me == 'C':
        # If earlier opponent was fully cooperative, this is likely noise -> forgive sometimes
        if opp_def_total == 1 and n >= 4:
            return 'D' if rng.random() < 0.5 else 'C'
        return 'D'

    # If opponent just defected and we also defected: try to break cycle
    if last_opp == 'D' and last_me == 'D':
        # Wait for CC signal
        if n >= 3 and opp[-2] == 'C' and opp[-3] == 'C':
            return 'C'
        if opp_def_total * 3 < n:
            # Generally cooperative opponent stuck in a spat -> forgive
            if rng.random() < 0.5:
                return 'C'
        return 'D'

    # Opponent cooperated last
    if last_opp == 'C':
        # If we've been defecting too much, return to cooperation to rebuild
        if me_def10 >= 4:
            return 'C'
        # Exploit a very cooperative opponent at a steady but modest rate
        if n >= 15 and opp_def_total * 5 <= n:
            if n >= 85:
                return 'D'
            if rng.random() < 0.12:
                return 'D'
        # If opponent cooperates but has a few defections, cooperate
        return 'C'

    return 'C'
